// Sentientia LMS Live — chart updater — Phase E.5.b.
//
// Listens for the 'sentientia-live:response_added' CustomEvent
// (dispatched by audience_sse / trainer_sse on the SSE response_added
// event) and mutates the result panel DOM in place. NO innerHTML —
// only textContent + style.width are mutated, so this is XSS-safe
// even if the server payload were tampered with.
//
// Supported types for inline update:
//   - multichoice / quiz: each [data-option-index="N"] row gets its
//     .sentientia-bar style.width updated proportionally to max count,
//     .sentientia-bar-count textContent updated, .sentientia-bar-percent
//     updated.
//   - rating: each [data-rating-value="V"] row gets the same treatment,
//     plus the .sentientia-results-avg + .sentientia-results-count
//     summary numbers update.
//
// Unsupported types (wordcloud / openended / ranking) fall back to
// window.location.reload() since their DOM structure changes shape
// (new tags / new cards / reordered table) which would require
// careful escaping to build via JS — deferred to Phase E.6.
define('local_sentientia_live/chart_updater', [], function() {
    'use strict';

    var INLINE_UPDATE_TYPES = ['multichoice', 'quiz', 'rating'];

    function init() {
        window.addEventListener(
            'sentientia-live:response_added', handleResponseAdded);
    }

    function handleResponseAdded(ev) {
        if (!ev.detail) { return; }
        var slideId   = ev.detail.slide_id;
        var slideType = ev.detail.slide_type;
        var countNow  = ev.detail.count_now;
        var tally     = ev.detail.tally;

        // Always update the visible total counter, regardless of type.
        var totalEl = document.querySelector(
            '.sentientia-results-panel[data-slideid="' + slideId + '"]'
            + ' .sentientia-results-total');
        if (totalEl && typeof countNow === 'number') {
            totalEl.textContent = String(countNow);
        }

        if (INLINE_UPDATE_TYPES.indexOf(slideType) === -1) {
            // For types we can't update inline, full reload after a
            // short debounce so we don't reload mid-keystroke if the
            // user is e.g. typing a wordcloud entry.
            setTimeout(function() { window.location.reload(); }, 500);
            return;
        }

        if (!tally) { return; }

        var panel = document.querySelector(
            '.sentientia-results-panel[data-slideid="' + slideId + '"]');
        if (!panel) { return; }

        if (slideType === 'multichoice' || slideType === 'quiz') {
            updateBarChart(panel, tally);
        } else if (slideType === 'rating') {
            updateRatingChart(panel, tally);
        }
    }

    /**
     * Multichoice / quiz: tally is a {optionIdx => count} map (with
     * sequential 0-N indices the server sends as a JSON array OR an
     * object depending on PHP). Compute max for bar normalisation,
     * then iterate each [data-option-index] row.
     */
    function updateBarChart(panel, tally) {
        var counts = Object.values(tally).map(function(v) {
            return typeof v === 'number' ? v : 0;
        });
        var total = counts.reduce(function(a, b) { return a + b; }, 0);
        var max   = counts.reduce(function(a, b) {
            return Math.max(a, b);
        }, 0);

        var rows = panel.querySelectorAll('.sentientia-bar-row');
        rows.forEach(function(row) {
            var idx = parseInt(row.dataset.optionIndex, 10);
            if (isNaN(idx)) { return; }
            var count   = (typeof tally[idx] === 'number') ? tally[idx]
                : (typeof tally[String(idx)] === 'number') ? tally[String(idx)]
                : 0;
            var percent = total > 0 ? Math.round((count / total) * 100) : 0;
            var barPc   = max   > 0 ? Math.round((count / max  ) * 100) : 0;

            var bar = row.querySelector('.sentientia-bar');
            if (bar) {
                bar.style.width = barPc + '%';
            }
            var countEl = row.querySelector('.sentientia-bar-count');
            if (countEl) {
                countEl.textContent = String(count);
            }
            var pctEl = row.querySelector('.sentientia-bar-percent');
            if (pctEl) {
                pctEl.textContent = String(percent);
            }
        });
    }

    /**
     * Rating: tally has numeric keys + _avg + _count special fields.
     * Update each [data-rating-value] row's bar + count, plus the
     * summary avg + count numbers.
     */
    function updateRatingChart(panel, tally) {
        // Find max excluding the _avg / _count special keys.
        var max = 0;
        Object.keys(tally).forEach(function(k) {
            if (k === '_avg' || k === '_count') { return; }
            var v = tally[k];
            if (typeof v === 'number' && v > max) {
                max = v;
            }
        });

        var rows = panel.querySelectorAll('[data-rating-value]');
        rows.forEach(function(row) {
            var v = row.dataset.ratingValue;
            var count = (typeof tally[v] === 'number') ? tally[v]
                : (typeof tally[parseInt(v, 10)] === 'number') ? tally[parseInt(v, 10)]
                : 0;
            var barPc = max > 0 ? Math.round((count / max) * 100) : 0;

            var bar = row.querySelector('.sentientia-bar');
            if (bar) {
                bar.style.width = barPc + '%';
            }
            var countEl = row.querySelector('.sentientia-bar-count');
            if (countEl) {
                countEl.textContent = String(count);
            }
        });

        // Avg + count summary.
        var avgEl = panel.querySelector('.sentientia-results-avg');
        if (avgEl && tally._avg !== undefined && tally._avg !== null) {
            avgEl.textContent = String(tally._avg);
        }
        var countSummaryEl = panel.querySelector('.sentientia-results-count');
        if (countSummaryEl && typeof tally._count === 'number') {
            countSummaryEl.textContent = String(tally._count);
        }
    }

    return {
        init: init
    };
});
